def report_checkpoint(config, node: str, status: str) -> None:
    callback = (config or {}).get("configurable", {}).get("checkpoint_callback")
    if callback:
        callback(node, status)

def format_documents(documents: list) -> str:
    """Format retrieved passages with source metadata for the LLM prompts."""
    if not documents:
        return "No relevant manual passage was retrieved."

    passages = []
    for index, document in enumerate(documents, start=1):
        source = document.metadata.get("source", "equipment manual")
        page = document.metadata.get("page")
        location = f"{source}, page {page + 1}" if page is not None else source
        passages.append(f"Passage {index} ({location}):\n{document.page_content}")

    return "\n\n".join(passages)

def parse_json_response(content: str) -> dict:
    """Parse plain or fenced JSON returned by the local LLM."""
    cleaned = content.strip()
    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`").removeprefix("json").strip()

    try:
        parsed = json.loads(cleaned)
    except json.JSONDecodeError:
        approved_marker = re.search(
            r'"approved"\s*:\s*(true|false)', content, re.IGNORECASE
        )
        if approved_marker:
            return {"approved": approved_marker.group(1).lower() == "true"}
        return {}

    return parsed if isinstance(parsed, dict) else {}

def retrieve_agent(state: AgentState, config=None):
    report_checkpoint(config, "retrieve", "started")

    readings = state["readings"]

    retrieved = []

    for reading in readings:

        query = (
            f"{reading['component']} "
            f"{reading['parameter']} "
            f"{reading['value']} "
            f"{reading['unit']}"
        )

        docs = vector_store.similarity_search(
            query,
            k=1,
            filter={
                "$and": [
                    {"component": reading["component"]},
                    {"parameter": reading["parameter"]},
                    {"unit": reading["unit"]},
                ]
            },
        )

        retrieved.append({
            "reading": reading,
            "documents": docs
        })


    result = {
        "retrieved_context": retrieved
    }
    report_checkpoint(config, "retrieve", "completed")
    return result

def explain_agent(state: AgentState, config=None):
    report_checkpoint(config, "explain", "started")

    explanations = []
    non_normal_explanation_duration = 0.0

    total_detections = len(state["detections"])
    for index, (detection, validation) in enumerate(
        zip(state["detections"], state["validations"]), start=1
    ):
        reading = detection["reading"]
        reading_label = (
            f"{index}/{total_detections} "
            f"{reading['component']} / {reading['parameter']}"
        )
        report_checkpoint(config, "explain", f"{reading_label} started")
        if not validation["approved"]:
            verification_notice = (
                "IMPORTANT: This result could not be verified against the "
                "retrieved manual. The document may be unclear or insufficient. "
                "Present the prediction as unverified and do not state it as fact."
            )
        else:
            verification_notice = (
                "The result was supported by the retrieved manual evidence."
            )

        prompt = f"""
You are an industrial maintenance explanation agent.

Reading:
{detection["reading"]}

Validated detection:
{detection["result"]}

Validated severity:
{validation["severity"]}

Validation:
{validation["reason"]}

Source manual passage:
{detection["manual_text"]}

Verification status:
{verification_notice}

Write a concise operator-facing explanation. Use the validated severity above
exactly; do not recalculate or change it. Cite the relevant manual passage
verbatim or by passage label, explain the likely condition, and recommend only
an action supported by the passage. Do not add unsupported facts. Return JSON
with exactly: evidence, likely_condition, and recommended_action.
"""

        result = llm.invoke(prompt)
        explanations.append({
            "reading": detection["reading"],
            "explanation": (
                result.content
                if validation["approved"]
                else f"{verification_notice}\n\n{result.content}"
            ),
        })
        report_checkpoint(config, "explain", f"{reading_label} completed")

    result = {
        "explanations": explanations,
        "post_detection_duration": (
            time.perf_counter() - state["post_detection_started_at"]
        ),
        "non_normal_post_detection_duration": (
            state["non_normal_validation_duration"]
            + non_normal_explanation_duration
        ),
    }
    report_checkpoint(config, "explain", "completed")
    return result

def load_sample_readings() -> list[dict]:
    sample_path = BASE_DIR / "sample_readings.json"
    sample_readings = json.loads(sample_path.read_text(encoding="utf-8"))
    return [
        {
            "component": reading["component"],
            "parameter": reading["parameter"],
            "value": reading["value"],
            "unit": reading["unit"],
        }
        for reading in sample_readings
    ]

def parse_result(raw: str) -> dict:
    cleaned = raw.strip()
    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`").removeprefix("json").strip()
    try:
        value = json.loads(cleaned)
        return value if isinstance(value, dict) else {}
    except json.JSONDecodeError:
        return {}

def detected_severity(raw: str) -> str:
    """Return the selected severity, avoiding labels mentioned in reasoning."""
    parsed = parse_result(raw)
    for key in ("severity", "status", "classification", "decision", "category", "level"):
        value = str(parsed.get(key, "")).upper()
        if value in {"NORMAL", "WARNING", "FAULT"}:
            return value

    selected = re.search(
        r'"?(?:severity|status|classification|decision|category|level)"?\s*:\s*'
        r'"?\*{0,2}(NORMAL|WARNING|FAULT)\b'
        r'|(?:reading is|conclude that the reading is|severity is)\s*:?\s*\*{0,2}'
        r"(NORMAL|WARNING|FAULT)\b",
        raw,
        re.IGNORECASE,
    )
    if not selected:
        return "UNKNOWN"
    return next(group.upper() for group in selected.groups() if group)

def initial_readings() -> pd.DataFrame:
    sample_path = Path(__file__).with_name("sample_readings.json")
    with sample_path.open(encoding="utf-8") as sample_file:
        sample_readings = json.load(sample_file)
    return pd.DataFrame(sample_readings)

